using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.ShippedDate)
                .ToListAsync();
            return Results.Ok(shipments.Select(MapToDto));
        });

        group.MapGet("/my", async (ApplicationDbContext db, HttpContext ctx) =>
        {
            var email = ctx.User.Identity?.Name ?? string.Empty;
            var shipments = await db.Shipments
                .Where(s => s.CustomerEmail == email)
                .OrderByDescending(s => s.ShippedDate)
                .ToListAsync();
            return Results.Ok(shipments.Select(MapToDto));
        });

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(MapToDto(shipment));
        });

        group.MapPut("/{id:int}/status", async (int id, StatusUpdateRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = request.Status;
            if (request.Status == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(MapToDto(shipment));
        });
    }

    private static object MapToDto(Shipment s) => new
    {
        s.Id,
        s.TrackingNumber,
        s.Origin,
        s.Destination,
        Status = (int)s.Status,
        s.ShippedDate,
        s.EstimatedDelivery,
        s.ActualDelivery,
        s.CustomerEmail,
        s.Description
    };

    public record StatusUpdateRequest(ShipmentStatus Status);
}

